233		if r.Method == http.MethodGet {
234			rawItems, err := s.stateStore.ListState(r.Context(), store.LostPetsCollection)
235			if err != nil {
236				http.Error(w, "Failed to query lost pets", http.StatusInternalServerError)
237				return
