239	
240			params := parseQueryParams(r)
241	
242			pets := make([]domain.LostPetEvent, 0, len(rawItems))
243			for _, b := range rawItems {
244				var pet domain.LostPetEvent
245				if err := json.Unmarshal(b, &pet); err == nil {
246					// Species filter check
247					if params.Species != "" {
248						var rawMap map[string]any
249						_ = json.Unmarshal(b, &rawMap)
250						if sp, ok := rawMap["species"].(string); ok && sp != "" {
251							if !strings.EqualFold(sp, params.Species) {
252								continue
253							}
254						}
255					}
256					// Geo radius filter
257					if params.HasGeo {
258						locPt := domain.ParseLocationCoordinates(pet.Location)
259						dist := domain.HaversineDistanceMiles(params.GeoPoint, locPt)
260						if dist > params.RadiusMiles {
261							continue
262						}
263					}
264					pets = append(pets, pet)
265				}
266			}
267	
268			totalCount := len(pets)
269			w.Header().Set("X-Total-Count", strconv.Itoa(totalCount))
270	
271			// Apply pagination limit & offset
272			if params.Offset > len(pets) {
273				pets = []domain.LostPetEvent{}
274			} else {
275				end := params.Offset + params.Limit
276				if end > len(pets) {
277					end = len(pets)
278				}
279				pets = pets[params.Offset:end]
280			}
281	
282			publicPets := make([]PublicLostPet, 0, len(pets))
