	_ "image/jpeg"
	_ "image/png"
	"net/http"
	"net/url"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ErrNotFound indicates the requested blob image was not found.
var ErrNotFound = errors.New("blob: image not found")

var (
	// ErrInvalidImage indicates that an upload is not a supported, valid image.
	ErrInvalidImage = errors.New("blob: invalid image")
	// ErrUploadMismatch indicates that an upload does not belong to the report being finalized.
	ErrUploadMismatch = errors.New("blob: upload does not belong to report")
	// ErrUploadExpired indicates that the upload can no longer create report state.
	ErrUploadExpired = errors.New("blob: upload finalize capability expired")
	// ErrNotFinalized indicates that a private read was requested before validation completed.
	ErrNotFinalized = errors.New("blob: image is not finalized")
)

const (
	// MaxImageBytes is the largest accepted pet image.
	MaxImageBytes     int64 = 10 << 20
	uploadExpiry            = 15 * time.Minute
	maxReadExpiry           = 15 * time.Minute
	maxImageDimension       = 12_000
	maxImagePixels          = 40_000_000
	// DefaultOrphanGracePeriod prevents cleanup from racing active report creation.
	DefaultOrphanGracePeriod = 24 * time.Hour
	// MaxOrphanCleanupBatch bounds one reconciliation pass.
	MaxOrphanCleanupBatch = 100
)

// ImagePurpose scopes a generated object key to an application workflow.
type ImagePurpose string

// ImagePurposeFoundPet identifies an image for a found-pet report.
const ImagePurposeFoundPet ImagePurpose = "found-pet"

// ImageUploadIntent contains the trusted attributes needed to create a direct-upload grant.
// FileName is advisory only and is never used in the generated object key.
type ImageUploadIntent struct {
	Purpose     ImagePurpose `json:"purpose"`
	FileName    string       `json:"fileName,omitempty"`
	ContentType string       `json:"contentType"`
}

// ImageUploadGrant describes a short-lived, policy-constrained direct upload.
type ImageUploadGrant struct {
	UploadURL     string            `json:"uploadUrl"`
	FormFields    map[string]string `json:"formFields"`
	ReportID      string            `json:"reportId"`
	FinalizeToken string            `json:"finalizeToken"`
	ObjectName    string            `json:"objectName"`
	ContentType   string            `json:"contentType"`
	MaxBytes      int64             `json:"maxBytes"`
	ExpiresAt     time.Time         `json:"expiresAt"`
}

// FinalizedImage is a validated private image object.
type FinalizedImage struct {
	ObjectName  string `json:"objectName"`
	ContentType string `json:"contentType"`
	Size        int64  `json:"size"`
	Width       int    `json:"width"`
	Height      int    `json:"height"`
	Generation  int64  `json:"generation"`
}

// ImageStore defines the secure direct-upload and private-read lifecycle.
type ImageStore interface {
	BeginImageUpload(ctx context.Context, intent ImageUploadIntent) (*ImageUploadGrant, error)
	FinalizeImage(ctx context.Context, reportID, objectName, finalizeToken string) (*FinalizedImage, error)
	ReadFinalizedImage(ctx context.Context, objectName string) ([]byte, error)
	GenerateImageReadURL(ctx context.Context, objectName string, expiry time.Duration) (string, error)
}

// FinalizedImageReferenceChecker reports whether durable report state refers
// to the exact finalized object.
type FinalizedImageReferenceChecker func(ctx context.Context, reportID, objectName string) (bool, error)

// OrphanCleaner reconciles finalized images left behind by a process crash or
// report-persistence failure.
type OrphanCleaner interface {
	CleanupOrphanedFinalizedImages(
		ctx context.Context,
		createdBefore time.Time,
		limit int,
		referenced FinalizedImageReferenceChecker,
	) (int, error)
}

// PresignedURLResponse encapsulates direct-to-cloud upload pre-signed parameters.
type PresignedURLResponse struct {
	UploadURL string    `json:"uploadUrl"`
	PublicURL string    `json:"publicUrl"`
	FileName  string    `json:"fileName"`
	ExpiresAt time.Time `json:"expiresAt"`
}

// BlobStore defines image/blob storage operations.
type BlobStore interface {
	UploadImage(ctx context.Context, fileName string, data []byte) (string, error)
	GetImage(ctx context.Context, fileName string) ([]byte, error)
	GeneratePresignedUploadURL(ctx context.Context, fileName, contentType string, expiry time.Duration) (*PresignedURLResponse, error)
}

// MemoryBlobStore implements BlobStore in memory for testing and local dev.
type MemoryBlobStore struct {
	mu                sync.RWMutex
	baseURL           string
	blobs             map[string][]byte
	pending           map[string]pendingImageUpload
	finalized         map[string]FinalizedImage
	finalizedByUpload map[string]string
	finalizeTokens    map[string]string
	finalizeBefore    map[string]time.Time
	now               func() time.Time
}

type pendingImageUpload struct {
	reportID    string
	contentType string
	finalName   string
	expiresAt   time.Time
	tokenDigest string
}

// NewMemoryBlobStore constructs a MemoryBlobStore with a base URL prefix.
func NewMemoryBlobStore(baseURL string) *MemoryBlobStore {
	return &MemoryBlobStore{
		baseURL:           strings.TrimSuffix(baseURL, "/"),
		blobs:             make(map[string][]byte),
		pending:           make(map[string]pendingImageUpload),
		finalized:         make(map[string]FinalizedImage),
		finalizedByUpload: make(map[string]string),
		finalizeTokens:    make(map[string]string),
		finalizeBefore:    make(map[string]time.Time),
		now:               time.Now,
	}
}

// UploadImage stores image bytes in memory and returns its public URL.
func (m *MemoryBlobStore) UploadImage(ctx context.Context, fileName string, data []byte) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}

	m.mu.Lock()
	defer m.mu.Unlock()

	m.blobs[fileName] = bytes.Clone(data)
	return fmt.Sprintf("%s/%s", m.baseURL, fileName), nil
}

// GetImage retrieves image bytes by fileName.
func (m *MemoryBlobStore) GetImage(ctx context.Context, fileName string) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	m.mu.RLock()
	defer m.mu.RUnlock()

	data, exists := m.blobs[fileName]
	if !exists {
		return nil, ErrNotFound
	}
	return bytes.Clone(data), nil
}

// GeneratePresignedUploadURL constructs a pre-signed HTTP PUT upload URL for direct cloud storage uploads.
func (m *MemoryBlobStore) GeneratePresignedUploadURL(ctx context.Context, fileName, contentType string, expiry time.Duration) (*PresignedURLResponse, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	if expiry <= 0 {
		expiry = 15 * time.Minute
	}

	cleanFileName := strings.TrimSpace(fileName)
	if cleanFileName == "" {
		cleanFileName = fmt.Sprintf("upload-%d.jpg", time.Now().UnixNano())
	}

	expiresAt := time.Now().UTC().Add(expiry)
	token, err := randomHex(24)
	if err != nil {
		return nil, err
	}
	uploadURL := fmt.Sprintf("%s/upload/presigned/%s?expires=%d&token=%s", m.baseURL, cleanFileName, expiresAt.Unix(), token)
	publicURL := fmt.Sprintf("%s/%s", m.baseURL, cleanFileName)

	return &PresignedURLResponse{
		UploadURL: uploadURL,
		PublicURL: publicURL,
		FileName:  cleanFileName,
		ExpiresAt: expiresAt,
	}, nil
}

// BeginImageUpload creates a server-owned object name and constrained upload grant.
func (m *MemoryBlobStore) BeginImageUpload(ctx context.Context, intent ImageUploadIntent) (*ImageUploadGrant, error) {
package blob

import (
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"cloud.google.com/go/storage"
	"google.golang.org/api/googleapi"
	"google.golang.org/api/iterator"
	"google.golang.org/api/option"
)

const (
	metadataReportID         = "petspotr-report-id"
	metadataPurpose          = "petspotr-purpose"
	metadataWidth            = "petspotr-width"
	metadataHeight           = "petspotr-height"
	metadataUploadToken      = "petspotr-upload-token-sha256"
	metadataFinalizeBefore   = "petspotr-finalize-before"
	metadataReportIDField    = "x-goog-meta-" + metadataReportID
	metadataPurposeField     = "x-goog-meta-" + metadataPurpose
	metadataUploadTokenField = "x-goog-meta-" + metadataUploadToken
	metadataFinalizeField    = "x-goog-meta-" + metadataFinalizeBefore
)

// GCSConfig configures a private Google Cloud Storage image store.
type GCSConfig struct {
	BucketName     string
	Endpoint       string
	GoogleAccessID string
	PrivateKey     []byte
}

// GCSImageStore implements the secure image lifecycle in a private GCS bucket.
type GCSImageStore struct {
	backend       gcsBackend
	cleanupMu     sync.Mutex
	cleanupCursor string
	now           func() time.Time
}

type gcsObjectAttrs struct {
	Name        string
	ContentType string
	Size        int64
	Generation  int64
	Created     time.Time
	Metadata    map[string]string
}

type gcsBackend interface {
	GenerateSignedPostPolicyV4(string, *storage.PostPolicyV4Options) (*storage.PostPolicyV4, error)
	Attrs(context.Context, string) (gcsObjectAttrs, error)
	Read(context.Context, string, int64, int64) ([]byte, error)
	Copy(context.Context, string, string, int64, gcsObjectAttrs) (gcsObjectAttrs, error)
	Delete(context.Context, string, int64) error
	SignedURL(string, *storage.SignedURLOptions) (string, error)
	List(context.Context, string, string, int) ([]gcsObjectAttrs, string, error)
	Close() error
}

type googleStorageBackend struct {
	client         *storage.Client
	bucket         *storage.BucketHandle
	googleAccessID string
	privateKey     []byte
	hostname       string
	insecure       bool
}

// NewGCSImageStore constructs a managed or emulator-backed GCS image store.
// Managed mode leaves signing credentials empty so the supported client
// library can use Application Default Credentials and IAM signBlob.
func NewGCSImageStore(ctx context.Context, config GCSConfig) (*GCSImageStore, error) {
	config.BucketName = strings.TrimSpace(config.BucketName)
	if config.BucketName == "" {
		return nil, errors.New("blob: GCS bucket name is required")
	}
	clientOptions := make([]option.ClientOption, 0, 2)
	endpoint := strings.TrimSpace(config.Endpoint)
	if endpoint != "" {
		clientOptions = append(clientOptions, option.WithEndpoint(endpoint), option.WithoutAuthentication())
	}
	client, err := storage.NewClient(ctx, clientOptions...)
	if err != nil {
		return nil, fmt.Errorf("blob: create GCS client: %w", err)
	}
	backend := &googleStorageBackend{
		client:         client,
		bucket:         client.Bucket(config.BucketName),
		googleAccessID: strings.TrimSpace(config.GoogleAccessID),
		privateKey:     config.PrivateKey,
		hostname:       endpoint,
		insecure:       strings.HasPrefix(endpoint, "http://"),
	}
	return newGCSImageStore(backend), nil
}

func newGCSImageStore(backend gcsBackend) *GCSImageStore {
	return &GCSImageStore{backend: backend, now: time.Now}
}

// BeginImageUpload creates a V4 POST policy constrained to one generated key,
// one supported media type, exact metadata, a short expiry, and MaxImageBytes.
func (s *GCSImageStore) BeginImageUpload(ctx context.Context, intent ImageUploadIntent) (*ImageUploadGrant, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if intent.Purpose != ImagePurposeFoundPet {
		return nil, fmt.Errorf("%w: unsupported purpose %q", ErrInvalidImage, intent.Purpose)
	}
	contentType, extension, ok := supportedImageType(intent.ContentType)
	if !ok {
		return nil, fmt.Errorf("%w: unsupported content type %q", ErrInvalidImage, intent.ContentType)
	}
	token, err := randomHex(16)
	if err != nil {
		return nil, err
	}
	reportID := "found-" + token
	finalizeToken, err := randomHex(32)
	if err != nil {
		return nil, err
	}
	objectName := fmt.Sprintf("uploads/found-pets/%s/image%s", reportID, extension)
	expiresAt := s.now().UTC().Add(uploadExpiry)
	policy, err := s.backend.GenerateSignedPostPolicyV4(objectName, &storage.PostPolicyV4Options{
		Expires: expiresAt,
		Fields: &storage.PolicyV4Fields{
			ContentType:         contentType,
			StatusCodeOnSuccess: http.StatusCreated,
			Metadata: map[string]string{
				metadataReportIDField:    reportID,
				metadataPurposeField:     string(ImagePurposeFoundPet),
				metadataUploadTokenField: tokenDigest(finalizeToken),
				metadataFinalizeField:    strconv.FormatInt(expiresAt.Unix(), 10),
			},
		},
		Conditions: []storage.PostPolicyV4Condition{
			storage.ConditionContentLengthRange(1, uint64(MaxImageBytes)),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("blob: sign GCS upload policy: %w", err)
	}
	return &ImageUploadGrant{
		UploadURL:     policy.URL,
		FormFields:    policy.Fields,
		ReportID:      reportID,
		FinalizeToken: finalizeToken,
		ObjectName:    objectName,
		ContentType:   contentType,
		MaxBytes:      MaxImageBytes,
		ExpiresAt:     expiresAt,
	}, nil
}

// FinalizeImage verifies immutable object attributes and decoded bytes before
// copying the object into the private finalized namespace.
func (s *GCSImageStore) FinalizeImage(ctx context.Context, reportID, objectName, finalizeToken string) (*FinalizedImage, error) {
	contentType, finalName, err := validateUploadBinding(reportID, objectName)
	if err != nil {
		return nil, err
	}

	if attrs, attrsErr := s.backend.Attrs(ctx, finalName); attrsErr == nil {
		if !tokenMatches(attrs.Metadata[metadataUploadToken], finalizeToken) {
			return nil, ErrUploadMismatch
		}
		if err := s.validateFinalizeDeadline(attrs.Metadata); err != nil {
			return nil, err
		}
		return finalizedFromAttrs(reportID, attrs)
	} else if !errors.Is(attrsErr, ErrNotFound) {
		return nil, fmt.Errorf("blob: inspect finalized GCS image: %w", attrsErr)
	}

	attrs, err := s.backend.Attrs(ctx, objectName)
	if err != nil {
		return nil, fmt.Errorf("blob: inspect uploaded GCS image: %w", err)
	}
	if attrs.Name != objectName || attrs.ContentType != contentType ||
		attrs.Metadata[metadataReportID] != reportID ||
		attrs.Metadata[metadataPurpose] != string(ImagePurposeFoundPet) {
		return nil, ErrUploadMismatch
	}
	if !tokenMatches(attrs.Metadata[metadataUploadToken], finalizeToken) {
		return nil, ErrUploadMismatch
	}
	if err := s.validateFinalizeDeadline(attrs.Metadata); err != nil {
		return nil, err
	}
	if attrs.Size <= 0 || attrs.Size > MaxImageBytes {
		return nil, fmt.Errorf("%w: object size %d", ErrInvalidImage, attrs.Size)
	}
	data, err := s.backend.Read(ctx, objectName, attrs.Generation, MaxImageBytes+1)
	if err != nil {
		return nil, fmt.Errorf("blob: read uploaded GCS image: %w", err)
	}
	if int64(len(data)) != attrs.Size {
		return nil, fmt.Errorf("%w: object size changed during validation", ErrInvalidImage)
	}
	width, height, err := validateImage(data, contentType)
	if err != nil {
		return nil, err
	}
	finalAttrs, err := s.backend.Copy(ctx, finalName, objectName, attrs.Generation, gcsObjectAttrs{
		ContentType: contentType,
		Size:        attrs.Size,
		Metadata: map[string]string{
			metadataReportID:       reportID,
			metadataPurpose:        string(ImagePurposeFoundPet),
			metadataWidth:          strconv.Itoa(width),
			metadataHeight:         strconv.Itoa(height),
			metadataUploadToken:    attrs.Metadata[metadataUploadToken],
			metadataFinalizeBefore: attrs.Metadata[metadataFinalizeBefore],
		},
	})
	if err != nil {
		if isPreconditionFailed(err) {
			if existing, attrsErr := s.backend.Attrs(ctx, finalName); attrsErr == nil {
				if !tokenMatches(existing.Metadata[metadataUploadToken], finalizeToken) {
					return nil, ErrUploadMismatch
				}
				if err := s.validateFinalizeDeadline(existing.Metadata); err != nil {
					return nil, err
				}
				return finalizedFromAttrs(reportID, existing)
			}
		}
		return nil, fmt.Errorf("blob: finalize GCS image: %w", err)
	}
