            foundPet: {
              petId: 'found-hostile-text',
              breed: `Retriever ${textPayload}`,
              imageUrl: 'https://attacker.example/tracking.png',
              location: `Green Lake ${textPayload}`,
            },
          },
          {
            matchId: `match-invalid" data-injected="true`,
            foundPetId: 'found-invalid',
            matchedPetId: 'lost-invalid',
            score: '1; background: url(javascript:alert(1))',
            status: 'PENDING_REVIEW',
            matchedAt: 'not-a-date',
            scores: {
              visual: '100%',
              color: 0.9,
              spatial: 0.88,
              distanceMiles: -1,
            },
            lostPet: {
              petId: 'lost-invalid',
              petName: 'Invalid record',
              breed: 'Unknown',
              imageUrl: 'https://storage.petspotr.io/lost-invalid.jpg',
              location: 'Unknown',
            },
            foundPet: {
              petId: 'found-invalid',
              breed: 'Unknown',
              imageUrl: 'https://storage.petspotr.io/found-invalid.jpg',
              location: 'Unknown',
            },
          },
          {
            matchId: 'match-legitimate',
            foundPetId: 'found-legitimate',
            matchedPetId: 'lost-legitimate',
