            foundPetId: 'found-hostile-text',
            matchedPetId: 'lost-hostile-text',
            score: 0.91,
            status: 'PENDING_REVIEW',
            matchedAt: '2026-08-14T12:00:00Z',
            scores: {
              visual: 0.95,
              color: 0.9,
              spatial: 0.88,
              distanceMiles: 2.4,
            },
            lostPet: {
              petId: 'lost-hostile-text',
              petName: textPayload,
              breed: `Golden "Retriever" ${textPayload}`,
              imageUrl: 'javascript:document.body.dataset.imageXss="executed"',
              location: `Capitol Hill </p>${textPayload}`,
            },
            foundPet: {
              petId: 'found-hostile-text',
              breed: `Retriever ${textPayload}`,
              imageUrl: 'https://attacker.example/tracking.png',
              location: `Green Lake ${textPayload}`,
            },
          },
          {
            matchId: `match-invalid" data-injected="true`,
            foundPetId: 'found-invalid',
            matchedPetId: 'lost-invalid',
            score: '1; background: url(javascript:alert(1))',
            status: 'PENDING_REVIEW',
            matchedAt: 'not-a-date',
            scores: {
              visual: '100%',
              color: 0.9,
              spatial: 0.88,
              distanceMiles: -1,
            },
            lostPet: {
              petId: 'lost-invalid',
              petName: 'Invalid record',
              breed: 'Unknown',
              imageUrl: 'https://storage.petspotr.io/lost-invalid.jpg',
              location: 'Unknown',
            },
            foundPet: {
              petId: 'found-invalid',
              breed: 'Unknown',
              imageUrl: 'https://storage.petspotr.io/found-invalid.jpg',
              location: 'Unknown',
            },
          },
          {
            matchId: 'match-legitimate',
            foundPetId: 'found-legitimate',
            matchedPetId: 'lost-legitimate',
            score: 0.92,
            status: 'PENDING_REVIEW',
            matchedAt: '2026-08-14T12:30:00Z',
            scores: {
              visual: 0.95,
              color: 0.9,
              spatial: 0.88,
              distanceMiles: 2.4,
